<template>
  <div id="entrance" class="theme-light body container list-page">
    <div class="main-list">
      <div id="tableList" class="table-list" style='overflow-y: unset;height: 100%'>
        <div class="table-list-box" style="overflow: hidden">
          <div style="display: flex;justify-content: space-between;padding: 0 20px;box-sizing: border-box;align-items: center;margin-bottom: 10px;padding-bottom: 10px;border-bottom: 1px solid #CECECE">
            <span >
              <img src="data:image/png;base64,"
                    height="40px"
                   style="vertical-align: middle;margin-left: 5px"
              />
            </span>

            <div style="display: flex;flex-direction: column">
<!--              <i class="nz-icon nz-icon-arrow-down"/>-->
              <div style="font-size: 18px;font-weight: 600;color: #333;margin-bottom: 3px;text-align: right" v-if="!dataJson.type"> {{dataJson.dashboard.data.name}} </div>
              <div style="font-size: 18px;font-weight: 600;color: #333;margin-bottom: 3px;text-align: right" v-if="dataJson.type"> Explore </div>
              <span>  {{dateFormat(dataJson.start * 1000)}} - {{dateFormat(dataJson.end * 1000)}} ({{dataJson.timezone}})</span>
            </div>
          </div>
          <div v-if="dataJson.type === 'dashboard'" id="dashboardScrollbar" class="box-content"  ref="dashboardScrollbar" style='overflow:hidden; overflow-y: auto;height: calc(100% - 72px);display: flex;flex-direction: column'>
            <chartList
              ref="chartList"
              name="dashboard"
              :dashboardId="'export'"
              :class="{'show-top': true}"
              :data-list="dataJson.charts.data.list"
              :dataJson = "dataJson.chartsData"
              :is-export-html="true"
              :nowTimeType="nowTimeType"
              :from="'dashboard'"
              :time-range="searchTime"
              @edit-chart="editChart"
              @on-refresh-time="refreshTime"
              @on-remove-chart="delChart"
              @on-add-group-item-chart="addGroupItem"
              @refreshPanel="refreshPanel"
              :loading="chartListLoading"
            />
          </div>
          <div v-if="dataJson.type == 1 || dataJson.type == 2 || dataJson.type == 'explore' " id="explore" class="explores" style='overflow:hidden;background: #fffffe; height: calc(100% - 72px);display: flex;flex-direction: column'>
            <exploreItem
              ref="exploreItem"
              :key="dataJson.type"
              :closable="false"
              :tab-index="dataJson.type"
            >
            </exploreItem>
          </div>
        </div>
      </div>

    </div>
    <span class="temp-dom"></span>
  </div>
</template>

<script>
import chartList from '@/components/chart/chartList.vue'
import exploreItem from '@/components/page/dashboard/explore/exploreItemHtml'
import moment from 'moment-timezone'
import { loadI18n } from '@/components/common/i18n'
import i18nData from '@/entrance/exportHtml/i18nData'
import bus from '@/libs/bus'
const dataJson = window.dataJson || {}
export default {
  name: 'Entrance',
  data () {
    return {
      dataJson: dataJson,
      searchTime: ['29/04/2022 10:00:54', '29/04/2022 11:00:54'],
      nowTimeType: { start_time: '[native Date Fri Apr 29 2022 10:00:54 GMT+0800 (中国标准时间)]', end_time: '[native Date Fri Apr 29 2022 11:00:54 GMT+0800 (中国标准时间)]' }
    }
  },
  components: {
    chartList: chartList,
    exploreItem
  },
  created () {
    this.$i18n.locale = this.dataJson.language
    loadI18n(i18nData)
    const localOffset = this.dataJson.timezone || moment.tz.guess()
    this.dataJson.timezone = localOffset
    localStorage.setItem('nz-sys-timezone', localOffset)
    localStorage.setItem('nz-default-dateFormat', 'YYYY-MM-DD HH:mm:ss')
    if (window.dataJson && (
      navigator.userAgent.match(/Mobi/i) ||
      navigator.userAgent.match(/Android/i) ||
      navigator.userAgent.match(/iPhone/i)
    )) {
      // 当前设备是移动设备
      document.body.style.minWidth = 'unset'
    }
    document.body.style.minWidth = 'unset'
    const arr = [{ id: 1, name: 'P1', color: '#eb1010', weight: 1, remark: 'Critical, alert that can cause business paralysis' }, { id: 2, name: 'P2', color: '#f89984', weight: 2, remark: 'Major, alert that requires urgent attention, but does not affect the business yet' }, { id: 3, name: 'P3', color: '#f7ba78', weight: 3, remark: 'Minor, alert that need to be dealt with, but not urgent' }]
    localStorage.setItem('nz-severityData', JSON.stringify(arr))
    localStorage.setItem('nz-severityDataWeight', JSON.stringify(arr))
  },
  mounted () {
    if (this.$refs.dashboardScrollbar) {
      this.scrollbarWrap = this.$refs.dashboardScrollbar
      this.onScroll()
    }
  },
  methods: {
    editChart () {},
    refreshTime () {},
    delChart () {},
    addGroupItem () {},
    chartListLoading () {},
    refreshPanel () {},
    // 时间戳转为UTC格式
    dateFormat (time) {
      let offset = localStorage.getItem('nz-sys-timezone')
      offset = moment.tz(offset).format('Z')
      return moment(time).utcOffset(offset).format()
    },
    onScroll () {
      const _self = this
      this.scrollbarWrap.addEventListener('scroll', bus.debounce(function () {
        _self.showTopBtn = _self.scrollbarWrap.scrollTop > 50
        _self.overScroll10 = _self.scrollbarWrap.scrollTop > 50
        _self.$refs.chartList.onScroll(_self.scrollbarWrap.scrollTop)
      }, 300, function () {
        _self.showTopLine = _self.scrollbarWrap.scrollTop > 10
      }))
    }
  }
}
</script>

<style>
  #entrance {
    font-family: Avenir, Helvetica, Arial, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-align: left;
    color: #2c3e50;
    margin-top: 10px;
  }
</style>
